package com.scriptles.cabinet.profile.entity;
import com.scriptles.cabinet.profile.enums.*; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="profile_posts",indexes=@Index(name="idx_profile_posts_public",columnList="author_profile_id,status,published_at")) @Getter @Setter @NoArgsConstructor
public class Post { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="author_profile_id",nullable=false) private Profile authorProfile; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private PostType type; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private PostStatus status=PostStatus.DRAFT; @Column(length=200) private String title; @Column(columnDefinition="TEXT") private String body; @Column(length=500) private String linkUrl; private Instant publishedAt; @CreationTimestamp private Instant createdAt; @UpdateTimestamp private Instant updatedAt; }
